  created_at DateTime @db.Timestamptz

  /// Timestamp when this session expires. Maximum session duration is 24 hours
  /// from creation. Sessions must be invalidated after this time regardless of
  /// activity. NOT NULL by default for security enforcement.
  expired_at DateTime @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  seller shopping_mall_sellers @relation(fields: [seller_id], references: [id], onDelete: Cascade)

  //----
  // INDEXES
  //----
  @@index([seller_id, created_at])
}

