  TestValidator.equals(
    "customer id matches",
    customer.id,
    customerAuthorized.id,
  );
  TestValidator.equals(
    "email matches",
    customer.email,
    customerAuthorized.email,
  );
  TestValidator.predicate(
    "banned is boolean",
    typeof customer.banned === "boolean",
  );
}

