    async () => {
      await api.functional.shoppingMall.seller.password.updatePassword(
        sellerConnection,
        {
          body: {
            current_password: wrongCurrentPassword,
            new_password: newPassword,
          } satisfies IShoppingMallActor.IPasswordUpdate,
        },
