    defaultResult.data.every(
      (v) => typeof v.id === "string" && v.id.length > 0,
    ),
  );
  TestValidator.predicate("all variants have valid SKU codes", () =>
    defaultResult.data.every(
      (v) => typeof v.skuCode === "string" && v.skuCode.length >= 3,
    ),
