export async function test_api_inventory_record_retrieval_by_administrator(
  connection: api.IConnection,
): Promise<void> {
  // Step 1: Administrator authentication
  const adminConnection: api.IConnection = { host: connection.host };
  const admin = await authorize_administrator_join(adminConnection, {});
  typia.assert(admin);
  // Step 2: Seller authentication and setup
  const sellerConnection: api.IConnection = { host: connection.host };
  const seller = await authorize_seller_join(sellerConnection, {});
  typia.assert(seller);
  // Step 3: Create a product
  const product =
    await generate_random_shopping_mall_seller_seller_products_create(
      sellerConnection,
      {},
    );
  typia.assert(product);
  // Step 4: Create a product variant
  const variant =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
      },
    );
  typia.assert(variant);
  // Step 5: Create a manual inventory adjustment
  const adjustmentReason = "Initial stock restock for testing";
  const inventoryRecord =
    await generate_random_shopping_mall_seller_variants_inventory_adjust(
      sellerConnection,
      {
        params: { variantId: variant.id },
        body: {
          quantity_change: 100,
          reason: adjustmentReason,
        },
      },
    );
  typia.assert(inventoryRecord);
  // Step 6: Administrator retrieves the inventory record
  const retrievedRecord =
    await api.functional.shoppingMall.administrator.variants.inventory.at(
      adminConnection,
      {
        variantId: variant.id,
        recordId: inventoryRecord.id,
      },
    );
  typia.assert(retrievedRecord);
  // Validations
  TestValidator.equals("record id", retrievedRecord.id, inventoryRecord.id);
  TestValidator.equals("variant id", retrievedRecord.variant_id, variant.id);
  TestValidator.equals("quantity change", retrievedRecord.quantity_change, 100);
  TestValidator.equals("reason", retrievedRecord.reason, adjustmentReason);
  TestValidator.equals("seller id", retrievedRecord.seller_id, seller.id);
  TestValidator.equals("order id is null", retrievedRecord.order_id, null);
  TestValidator.equals(
    "cancellation request id is null",
    retrievedRecord.cancellation_request_id,
    null,
  );
  TestValidator.equals(
    "refund request id is null",
    retrievedRecord.refund_request_id,
    null,
  );
  TestValidator.predicate(
    "created_at is present",
    retrievedRecord.created_at.length > 0,
  );
}

