  TestValidator.equals(
    "product reference matches",
    wishlistItem.product.id,
    product.id,
  );
  TestValidator.equals(
    "product name matches",
    wishlistItem.product.name,
    product.name,
  );
  TestValidator.predicate(
    "created_at timestamp is set",
    !!wishlistItem.created_at,
  );
