export async function test_api_order_item_authorization_other_customer_denied(
  connection: api.IConnection,
): Promise<void> {
  // 1. Setup: Create seller, product, variant, and inventory
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection, {});
  const product =
    await generate_random_shopping_mall_seller_seller_products_create(
      sellerConnection,
      {},
    );
  const variant =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
      },
    );
  await generate_random_shopping_mall_seller_variants_inventory_adjust(
    sellerConnection,
    {
      params: { variantId: variant.id },
      body: {
        quantity_change: 100,
        reason: "Initial stock for test",
      },
    },
  );
  // 2. Customer A: Register, add to cart, checkout
  const customerAConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerAConnection, {});
  await generate_random_shopping_mall_customer_customers_cart_items_create(
    customerAConnection,
    {
      body: {
        variantId: variant.id,
        quantity: 1,
      },
    },
  );
  const order = await generate_random_shopping_mall_customer_checkout_create(
    customerAConnection,
    {},
  );
  typia.assert(order);
  TestValidator.predicate(
    "Order should have items",
    order.orderItems.length > 0,
  );
  const orderItem = order.orderItems[0];
  // 3. Verify Customer A can access their own order item
  const ownOrderItem =
    await api.functional.shoppingMall.customer.orders.items.at(
      customerAConnection,
      {
        orderId: order.id,
        itemId: orderItem.id,
      },
    );
  typia.assert(ownOrderItem);
  TestValidator.equals(
    "Customer A can access own order item",
    ownOrderItem.id,
    orderItem.id,
  );
  // 4. Customer B: Register for unauthorized access attempt
  const customerBConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerBConnection, {});
  // 5. Authorization test: Customer B cannot access Customer A's order item
  await TestValidator.httpError(
    "Customer B denied access to Customer A's order item",
    404,
    async () => {
      await api.functional.shoppingMall.customer.orders.items.at(
        customerBConnection,
        {
          orderId: order.id,
          itemId: orderItem.id,
        },
      );
    },
  );
}

