  await TestValidator.httpError(
    "Customer B cannot access Customer A's refund request snapshot",
    403,
    async () => {
      await api.functional.shoppingMall.customer.refund_requests.snapshots.at(
        customerBConnection,
        {
          refundRequestId: refundRequest.id,
