export async function test_api_administrator_demote_unauthorized_regular(
  connection: api.IConnection,
): Promise<void> {
  // Step 1: Create a regular administrator who will attempt demotion
  const regularAdminConnection: api.IConnection = { host: connection.host };
  const regularAdmin = await authorize_administrator_join(
    regularAdminConnection,
    {},
  );
  typia.assert(regularAdmin);
  // Step 2: Create a second administrator to serve as demotion target
  const targetAdminConnection: api.IConnection = { host: connection.host };
  const targetAdmin = await authorize_administrator_join(
    targetAdminConnection,
    {},
  );
  typia.assert(targetAdmin);
  // Step 3: Verify regular admin has 'regular' grade (default from join)
  TestValidator.equals("regular admin grade", regularAdmin.grade, "regular");
  // Step 4: Regular admin attempts to demote target admin - should fail with 403
  await TestValidator.httpError(
    "regular admin cannot demote",
    403,
    async () => {
      await api.functional.shoppingMall.administrator.administrators.demote(
        regularAdminConnection,
        { administratorId: targetAdmin.id },
      );
    },
  );
}

