export async function test_api_product_image_reorder_main_thumbnail_change(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create seller-specific connection
  const sellerConnection: api.IConnection = { host: connection.host };
  const seller = await authorize_seller_join(sellerConnection, {});
  typia.assert(seller);
  // 2. Create a product
  const product =
    await generate_random_shopping_mall_seller_seller_products_create(
      sellerConnection,
      {},
    );
  typia.assert(product);
  // 3. Upload 3 images with sequential display_order
  const image1 =
    await generate_random_shopping_mall_seller_products_images_create(
      sellerConnection,
      {
        params: { productId: product.id },
        body: { displayOrder: 1 },
      },
    );
  typia.assert(image1);
  const image2 =
    await generate_random_shopping_mall_seller_products_images_create(
      sellerConnection,
      {
        params: { productId: product.id },
        body: { displayOrder: 2 },
      },
    );
  typia.assert(image2);
  const image3 =
    await generate_random_shopping_mall_seller_products_images_create(
      sellerConnection,
      {
        params: { productId: product.id },
        body: { displayOrder: 3 },
      },
    );
  typia.assert(image3);
  // Store original created_at timestamps for validation
  const originalTimestamps = new Map<string, string>([
    [image1.id, image1.createdAt],
    [image2.id, image2.createdAt],
    [image3.id, image3.createdAt],
  ]);
  // 4. Reorder images: reverse order (image3 -> position 1, image2 -> position 2, image1 -> position 3)
  // This makes image3 the new main thumbnail
  const reordered =
    await api.functional.shoppingMall.seller.products.images.reorder(
      sellerConnection,
      {
        productId: product.id,
        body: {
          imageIds: [image3.id, image2.id, image1.id],
          displayOrders: [1, 2, 3],
        } satisfies IShoppingMallProductImage.IReorder,
      },
    );
  typia.assert(reordered);
  // 5. Validate the reorder response
  // The API returns IShoppingMallProductImage.ISummary for the reordered image
  TestValidator.predicate(
    "returned image has valid display_order in range",
    () => reordered.display_order >= 1 && reordered.display_order <= 3,
  );
  TestValidator.predicate(
    "returned image is one of the reordered images",
    () =>
      reordered.id === image1.id ||
      reordered.id === image2.id ||
      reordered.id === image3.id,
  );
  // Validate created_at timestamp is preserved (data integrity)
  const originalCreatedAt = originalTimestamps.get(reordered.id);
  if (originalCreatedAt !== undefined) {
    TestValidator.equals(
      "created_at timestamp preserved after reorder",
      reordered.created_at,
      originalCreatedAt,
    );
  }
}

