                rejection_reason: true,
                suspended: true,
                banned: true,
                created_at: true,
                updated_at: true,
              },
            },
            images: {
              select: {
                image_url: true,
                display_order: true,
              },
              orderBy: { display_order: "asc" as const },
              take: 1,
            } satisfies Prisma.shopping_mall_product_imagesFindManyArgs,
