      const expiredAtFilter = buildDateFilter(expiredAtStart, expiredAtEnd);
      if (expiredAtFilter) where.expired_at = expiredAtFilter;
      return where;
    };
  const transformCustomerSession = (session: {
    id: string;
    ip: string | null;
    href: string | null;
    referrer: string | null;
    created_at: Date;
    expired_at: Date;
    customer: {
