      created_at: new Date(),
      updated_at: new Date(),
      deleted_at: null,
      customer: { connect: { id: props.customer.id } },
    },
    ...ShoppingMallAddressTransformer.select(),
  });
  // Return transformed result
  return await ShoppingMallAddressTransformer.transform(created);
